// Déterminer l'objectif cible et les paramètres (support universel des histoires guidées, rapides et titres)
const inputData = $input.item.json.body || $input.item.json || {};
const requestedKey = inputData.templateKey || inputData.template_key || inputData.objective || 'sleep';
const batchSize = Number(inputData.batchSize) || (requestedKey === 'title_generation_prompt' ? 30 : 20);

const TEMPLATE_MAP = {
  'sleep': { key: 'story_prompt_sleep', title: 'Histoire du Soir (Sommeil)', queryObjective: 'sleep' },
  'focus': { key: 'story_prompt_focus', title: 'Histoire Focus (Concentration)', queryObjective: 'focus' },
  'relax': { key: 'story_prompt_relax', title: 'Histoire Détente (Relaxation)', queryObjective: 'relax' },
  'fun': { key: 'story_prompt_fun', title: 'Histoire Ludique (S\'amuser)', queryObjective: 'fun' },
  'title_generation_prompt': { key: 'title_generation_prompt', title: '🎨 Génération Titres Jeunesse', queryObjective: 'all' },
  // Émotions rapides
  'fast_story_fear': { key: 'fast_story_fear', title: '⚡ Rapide — Peur', queryObjective: 'fast_story_fear' },
  'fast_story_anxiety': { key: 'fast_story_anxiety', title: '⚡ Rapide — Anxiété', queryObjective: 'fast_story_anxiety' },
  'fast_story_anger': { key: 'fast_story_anger', title: '⚡ Rapide — Colère', queryObjective: 'fast_story_anger' },
  'fast_story_sadness': { key: 'fast_story_sadness', title: '⚡ Rapide — Tristesse', queryObjective: 'fast_story_sadness' },
  'fast_story_stress': { key: 'fast_story_stress', title: '⚡ Rapide — Stress', queryObjective: 'fast_story_stress' },
  'fast_story_agitation': { key: 'fast_story_agitation', title: '⚡ Rapide — Agitation', queryObjective: 'fast_story_agitation' },
  'fast_story_guilt': { key: 'fast_story_guilt', title: '⚡ Rapide — Culpabilité', queryObjective: 'fast_story_guilt' },
  'fast_story_pain': { key: 'fast_story_pain', title: '⚡ Rapide — Douleur', queryObjective: 'fast_story_pain' },
  'fast_story_confidence': { key: 'fast_story_confidence', title: '⚡ Rapide — Confiance en soi', queryObjective: 'fast_story_confidence' },
  'fast_story_serenity': { key: 'fast_story_serenity', title: '⚡ Rapide — Sérénité', queryObjective: 'fast_story_serenity' },
  'fast_story_joy': { key: 'fast_story_joy', title: '⚡ Rapide — Joie', queryObjective: 'fast_story_joy' },
  'fast_story_courage': { key: 'fast_story_courage', title: '⚡ Rapide — Courage', queryObjective: 'fast_story_courage' },
  'fast_story_curiosity': { key: 'fast_story_curiosity', title: '⚡ Rapide — Curiosité', queryObjective: 'fast_story_curiosity' },
  'fast_story_empathy': { key: 'fast_story_empathy', title: '⚡ Rapide — Empathie', queryObjective: 'fast_story_empathy' },
  'fast_story_pride': { key: 'fast_story_pride', title: '⚡ Rapide — Fierté', queryObjective: 'fast_story_pride' },
  'fast_story_focus_skill': { key: 'fast_story_focus_skill', title: '⚡ Rapide — Concentration', queryObjective: 'fast_story_focus_skill' },
  'fast_story_creativity': { key: 'fast_story_creativity', title: '⚡ Rapide — Créativité', queryObjective: 'fast_story_creativity' },
  'fast_story_autonomy': { key: 'fast_story_autonomy', title: '⚡ Rapide — Autonomie', queryObjective: 'fast_story_autonomy' },
  // Situations du quotidien rapides
  'fast_story_situation_dark': { key: 'fast_story_situation_dark', title: '⚡ Rapide — Le Coucher', queryObjective: 'fast_story_situation_dark' },
  'fast_story_situation_school': { key: 'fast_story_situation_school', title: '⚡ Rapide — L\'École', queryObjective: 'fast_story_situation_school' },
  'fast_story_situation_separation': { key: 'fast_story_situation_separation', title: '⚡ Rapide — Séparation', queryObjective: 'fast_story_situation_separation' },
  'fast_story_situation_grief': { key: 'fast_story_situation_grief', title: '⚡ Rapide — Perte et Deuil', queryObjective: 'fast_story_situation_grief' },
  'fast_story_situation_conflict': { key: 'fast_story_situation_conflict', title: '⚡ Rapide — Conflit et Dispute', queryObjective: 'fast_story_situation_conflict' },
  'fast_story_situation_bedwetting': { key: 'fast_story_situation_bedwetting', title: '⚡ Rapide — Énurésie', queryObjective: 'fast_story_situation_bedwetting' },
  'fast_story_situation_medical': { key: 'fast_story_situation_medical', title: '⚡ Rapide — Soins Médicaux', queryObjective: 'fast_story_situation_medical' },
  'fast_story_situation_screens': { key: 'fast_story_situation_screens', title: '⚡ Rapide — Écrans', queryObjective: 'fast_story_situation_screens' }
};

let target = TEMPLATE_MAP[requestedKey];
if (!target) {
  if (requestedKey.startsWith('fast_story_')) {
    target = { key: requestedKey, title: `Histoire Rapide (${requestedKey.replace('fast_story_', '')})`, queryObjective: requestedKey };
  } else if (requestedKey.startsWith('story_prompt_')) {
    const shortObj = requestedKey.replace('story_prompt_', '');
    target = { key: requestedKey, title: `Objectif ${shortObj}`, queryObjective: shortObj };
  } else {
    target = { key: `story_prompt_${requestedKey}`, title: `Objectif ${requestedKey}`, queryObjective: requestedKey };
  }
}

return {
  json: {
    template_key: target.key,
    objective: target.queryObjective,
    title: target.title,
    batch_size: batchSize
  }
};

// Agrégation des retours critiques IA + retours parents réels + diversité des titres
const targetContext = $('Préparer Paramètres').item.json;
const activePromptData = $('Récupérer Prompt Actuel').item.json;
const storiesBatch = $input.all().map(i => i.json);

let currentPrompt = '';
if (Array.isArray(activePromptData) && activePromptData.length > 0) {
  currentPrompt = activePromptData[0].active_content || '';
} else if (activePromptData && activePromptData.active_content) {
  currentPrompt = activePromptData.active_content;
}

const isTitlePrompt = targetContext.template_key === 'title_generation_prompt';

// 1. Analyse des retours utilisateurs (Notes étoiles & commentaires)
const ratedStories = storiesBatch.filter(s => s.user_rating != null);
const userRatings = ratedStories.map(s => Number(s.user_rating));
const avgUserRating = userRatings.length > 0 
  ? (userRatings.reduce((a, b) => a + b, 0) / userRatings.length).toFixed(1) 
  : 'N/A';

const userComments = storiesBatch
  .filter(s => s.user_comment && s.user_comment.trim())
  .map(s => ({ rating: s.user_rating, comment: s.user_comment }));

// 2. Analyse des critiques IA
const critiqueScores = storiesBatch.filter(s => s.critique_score != null).map(s => Number(s.critique_score));
const avgCritiqueScore = critiqueScores.length > 0 
  ? (critiqueScores.reduce((a, b) => a + b, 0) / critiqueScores.length).toFixed(1) 
  : 'N/A';

// Extraction des titres réels
const recentTitles = storiesBatch.map(s => s.title).filter(Boolean).slice(0, 30);

// Extraction des faiblesses récurrentes
const weaknessesList = [];
const strengthsList = [];
const actionableList = [];
let excessiveOnomatopoeiaCount = 0;
let moralizingCount = 0;

storiesBatch.forEach(s => {
  if (Array.isArray(s.weaknesses)) {
    s.weaknesses.forEach(w => {
      if (w.issue) weaknessesList.push({ issue: w.issue, impact: w.impact, severity: w.severity });
    });
  }
  if (Array.isArray(s.strengths)) {
    s.strengths.forEach(st => {
      if (st.aspect) strengthsList.push({ aspect: st.aspect, analysis: st.analysis });
    });
  }
  if (Array.isArray(s.actionable_improvements)) {
    s.actionable_improvements.forEach(act => {
      if (act.recommendation) actionableList.push(act.recommendation);
    });
  }
  if (s.calmi_pitfalls) {
    if (s.calmi_pitfalls.excessive_onomatopoeia) excessiveOnomatopoeiaCount++;
    if (s.calmi_pitfalls.heavy_moralizing_detected) moralizingCount++;
  }
});

let userPrompt = '';
let systemPrompt = '';

if (isTitlePrompt) {
  userPrompt = `Voici les données pour le template de Génération de Titres (Clé: title_generation_prompt)\n\n--- PROMPT ACTUEL ---\n${currentPrompt}\n\n--- ÉCHANTILLON DES 30 DERNIERS TITRES CHOISIS EN PRODUCTION ---\n${JSON.stringify(recentTitles, null, 2)}\n\n--- RETOURS QUALITÉ GLOBAUX ---\n- Note moyenne des histoires : ${avgUserRating}/5\n- Score technique moyen IA : ${avgCritiqueScore}/10\n- Commentaires parents récents : ${JSON.stringify(userComments.slice(0, 8), null, 2)}\n\nGénère la nouvelle version optimisée du template de titres au format JSON requis.`;

  systemPrompt = `Tu es le Directeur Éditorial et Artistique en Chef de Calmi. Ton rôle est de perfectionner continuellement le template de prompt responsable de proposer 3 options de titres créatifs et poétiques avant la génération de l'histoire.\n\nCONSIGNES CALMI STRICTES POUR LE TEMPLATE DE TITRES :\n- Préserve scrupuleusement la variable indispensable {{objective}} et la référence à title_memory.\n- Format de sortie JSON STRICT exigé dans le prompt généré : { \"title_1\": \"...\", \"title_2\": \"...\", \"title_3\": \"...\", \"input_tokens\": \"string\", \"output_tokens\": \"string\", \"model_llm\": \"gpt-5\" }.\n- Style éditorial : inspiré de la sobriété et de l'élégance de L'école des loisirs ou Gallimard Jeunesse (mots concrets, sonores, évocateurs).\n- Règles linguistiques : Casse française stricte (majuscule UNIQUEMENT au premier mot et aux noms propres, JAMAIS de Title Case anglais).\n- Interdictions absolues : Aucun adjectif laudatif creux (ex: magique, merveilleux, incroyable, fantastique), aucun titre du type 'L'objet qui fait une action', aucun nom d'enfant dans le titre.\n- Tu dois répondre EXCLUSIVEMENT sous la forme d'un objet JSON valide contenant :\n  - \"improved_prompt\": le texte complet et révisé du template de titre.\n  - \"changelog\": un résumé clair, vulgarisé et concis (en français) expliquant ce qui a été affiné (variété, poésie, typographie, élimination des clichés).\n  - \"key_improvements\": une liste de 3 à 5 points clés d'amélioration.`;
} else {
  userPrompt = `Voici les données pour le template : ${targetContext.title} (Clé: ${targetContext.template_key})\n\n--- PROMPT ACTUEL ---\n${currentPrompt}\n\n--- STATISTIQUES DU LOT (${storiesBatch.length} histoires disponibles) ---\n- Note moyenne des parents : ${avgUserRating}/5 (sur ${ratedStories.length} avis)\n- Score technique moyen IA : ${avgCritiqueScore}/10\n- Alertes onomatopées excessives : ${excessiveOnomatopoeiaCount}\n- Alertes moralisation lourde : ${moralizingCount}\n\n--- COMMENTAIRES REELS DES PARENTS ---\n${JSON.stringify(userComments, null, 2)}\n\n--- PRINCIPALES FAIBLESSES TECHNIQUES DETECTEES ---\n${JSON.stringify(weaknessesList.slice(0, 12), null, 2)}\n\n--- POINTS FORTS A CONSERVER ---\n${JSON.stringify(strengthsList.slice(0, 8), null, 2)}\n\n--- RECOMMANDATIONS D'ACTION IA ---\n${JSON.stringify(actionableList.slice(0, 10), null, 2)}\n\nGénère la nouvelle version optimisée du template au format JSON requis.`;

  systemPrompt = `Tu es le Directeur Éditorial et Pédagogique en Chef de Calmi. Ton rôle est de perfectionner continuellement les templates de prompts de génération d'histoires pour enfants (histoires guidées du soir/détente et histoires rapides sur les émotions/situations du quotidien).\n\nCONSIGNES CALMI IMPORTANTES :\n- Préserves scrupuleusement la structure et les balises variables indispensables du prompt (ex: {{target_word_count}}, {{duration_minutes}}, {{children_names}}, {{children_context}}, {{narrative_schema}}, {{vakog_focus}}, {{symbolic_universe}}, {{ericksonian_technique}}, etc.).\n- Pour les histoires d'émotions ou situations rapides : dédramatiser avec douceur, offrir une clé d'autonomie bienveillante à l'enfant, éviter toute injonction culpabilisante ou ton professoral.\n- Renforces les règles 'Show Don't Tell', la musicalité de lecture à voix haute, et la douceur sensorielle.\n- Règle stricte onomatopées : maximum 2 à 3 dans toute l'histoire.\n- Tu dois répondre EXCLUSIVEMENT sous la forme d'un objet JSON valide contenant :\n  - \"improved_prompt\": le texte complet et révisé du template de prompt.\n  - \"changelog\": un résumé clair, vulgarisé et concis (en français) expliquant ce qui a été amélioré et pourquoi.\n  - \"key_improvements\": une liste de 3 à 5 points clés d'amélioration.`;
}

const openaiPayload = {
  model: "gpt-5.6-terra",
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: systemPrompt
    },
    {
      role: "user",
      content: userPrompt
    }
  ]
};

return {
  json: {
    template_key: targetContext.template_key,
    objective: targetContext.objective,
    title: targetContext.title,
    current_prompt: currentPrompt,
    openai_payload: openaiPayload,
    stats: {
      total_stories: storiesBatch.length,
      rated_count: ratedStories.length,
      avg_user_rating: avgUserRating,
      avg_critique_score: avgCritiqueScore,
      excessive_onomatopoeia_count: excessiveOnomatopoeiaCount,
      heavy_moralizing_count: moralizingCount
    }
  }
};

// Extraire la réponse JSON de gpt-5.6-terra
const rawResponse = $input.item.json;
const synthContext = $('Synthèse Retours & Critiques').item.json;

let parsedResult = {};
try {
  const messageContent = rawResponse.choices[0].message.content;
  parsedResult = typeof messageContent === 'string' ? JSON.parse(messageContent) : messageContent;
} catch (err) {
  throw new Error(`Erreur lors du parsing de la réponse gpt-5.6-terra: ${err.message}`);
}

const improvedPrompt = parsedResult.improved_prompt || '';
const changelog = parsedResult.changelog || 'Optimisation automatique continue par gpt-5.6-terra';
const keyImprovements = Array.isArray(parsedResult.key_improvements) 
  ? parsedResult.key_improvements.join(' | ') 
  : '';

const fullChangelog = `🤖 Auto-n8n (gpt-5.6-terra) — ${changelog}${keyImprovements ? ` [Points clés: ${keyImprovements}]` : ''}`;

return {
  json: {
    template_key: synthContext.template_key,
    objective: synthContext.objective,
    title: synthContext.title,
    new_content: improvedPrompt,
    changelog: fullChangelog,
    stats: synthContext.stats
  }
};

parameters.responseBody:
={
  "success": true,
  "message": "Auto-optimisation continue terminée avec succès via gpt-5.6-terra.",
  "result": $json
}
